#pragma once
static void testExtendedPdc(const juce::File& root){
 auto dir=root.getChildFile("pdc-extended");dir.createDirectory();Session s(dir);auto source=root.getChildFile("source.wav");s.importAudio(source,0,0);s.importAudio(source,1,0);
 juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> types;format.findAllTypesForFile(types,juce::File(STUDIO_SOURCE_ROOT).getChildFile("build/backend/StudioTestDelay_artefacts/Release/VST3/Studio Test Delay.vst3").getFullPathName());require(types.size()==1,"Extended delay scan failed");s.engine.getPluginManager().initialise();s.engine.getPluginManager().knownPluginList.addType(*types[0]);
 auto add=[&](int track,int index){auto item=s.edit->getPluginCache().createNewPlugin(te::ExternalPlugin::xmlTypeName,*types[0]);auto* p=dynamic_cast<te::ExternalPlugin*>(item.get());require(p!=nullptr,"Extended delay creation failed");s.trackAt(track).pluginList.insertPlugin(item,index,nullptr);p->initialiseFully();require(p->getAudioPluginInstance()!=nullptr,"Extended delay load failed");return p;};
 auto latency=[&](te::ExternalPlugin* p,int n){auto* generic=p->getAudioPluginInstance()->getParameters()[1];generic->setValueNotifyingHost(float(n)/4096.0f);p->flushPluginStateToValueTree();juce::MessageManager::getInstance()->runDispatchLoopUntil(20);};
 auto* a=add(0,0);auto* b=add(1,0);latency(a,257);latency(b,1000);auto input=readWave(source);int checks=0;float error=0;juce::Array<juce::var> cases;
 auto verify=[&](juce::String name,float factor){for(int block:{128,256}){auto out=dir.getChildFile(name+"-"+juce::String(block)+".wav");s.render(out,block);auto data=readWave(out);float e=0;for(int c=0;c<2;++c)for(int i=0;i<48000;++i)e=std::max(e,std::abs(data.getSample(c,i)-factor*input.getSample(c,i)));error=std::max(error,e);if(e>1e-6f)throw std::runtime_error(("Extended PDC failed: "+name).toStdString());auto* result=new juce::DynamicObject;result->setProperty("case",name);result->setProperty("block",block);result->setProperty("max_error",e);cases.add(juce::var(result));++checks;}};
 verify("different-latencies",2);latency(b,4096);verify("latency-increase",2);latency(b,0);verify("latency-zero",2);latency(b,63);verify("latency-decrease",2);
 b->setEnabled(false);verify("bypass",2);b->setEnabled(true);verify("reenable",2);b->deleteFromParent();verify("removed",2);
 auto bus=s.addBus();s.route(0,bus);auto* downstream=add(bus,0);latency(downstream,511);verify("serial-bus",2);
 s.route(0,-1);s.addSend(0,bus,0,false);verify("post-send-return",3);downstream->setEnabled(false);verify("return-bypass",3);downstream->setEnabled(true);latency(downstream,2048);verify("return-latency-change",3);
 s.save();s.reopen();verify("reopen",3);
 require(s.engine.getDeviceManager().deviceManager.getCurrentAudioDevice()==nullptr,"Extended PDC opened device");auto* report=new juce::DynamicObject;report->setProperty("checks",checks);report->setProperty("max_error",error);report->setProperty("cases",cases);report->setProperty("physical_device_opened",false);report->setProperty("scope","offline graph rebuilt between latency changes");dir.getChildFile("pdc-extended-result.json").replaceWithText(juce::JSON::toString(juce::var(report)));
}
